const cfg = $('Konfiguration').first().json;
const labels = $('Kategorien holen').first().json.items || [];
const lists = $('Einkaufslisten holen').first().json.items || [];

const norm = (s) => (s ?? '').toString().trim().toLowerCase();

// Zielliste bestimmen: Name aus der Konfiguration, sonst die erste Liste
const wanted = norm(cfg.shoppingListName);
const list = lists.find((l) => norm(l.name) === wanted) || lists[0];
if (!list) {
  throw new Error('Keine Einkaufsliste in Mealie gefunden.');
}

// Kategorien nur zuordnen, niemals neu anlegen
const labelByName = new Map(labels.map((l) => [norm(l.name), l]));

const ai = $input.first().json;
const extracted = Array.isArray(ai.items)
  ? ai.items
  : (ai.output && Array.isArray(ai.output.items) ? ai.output.items : []);

const unmatched = [];

const payload = extracted
  .map((it, i) => {
    const label = labelByName.get(norm(it.category)) || null;
    if (norm(it.category) && !label) unmatched.push(it.category);

    const note = [(it.unit ?? '').toString().trim(), (it.name ?? '').toString().trim()]
      .filter(Boolean)
      .join(' ');

    const qty = Number(it.quantity);

    return {
      shoppingListId: list.id,
      note,
      quantity: Number.isFinite(qty) && qty > 0 ? qty : 1,
      isFood: false,
      labelId: label ? label.id : null,
      checked: false,
      position: i,
    };
  })
  .filter((x) => x.note);

return [
  {
    json: {
      shoppingList: { id: list.id, name: list.name },
      payload,
      stats: {
        count: payload.length,
        categorized: payload.filter((p) => p.labelId).length,
        unmatchedCategories: [...new Set(unmatched)],
      },
    },
  },
];
